<template><el-dialog title="受控异常操作" :visible.sync="open" width="560px" :close-on-click-modal="false"><el-alert v-if="todo" :title="`${todo.business_no||'-'} · ${todo.title}`" :description="`当前状态：${todo.status}。危险操作会改变流程并写入不可删除的审计记录。`" type="warning" :closable="false" show-icon/><el-form ref="form" :model="form" :rules="rules" label-width="100px"><el-form-item label="操作" prop="action"><el-select v-model="form.action"><el-option label="强制完成" value="force-complete"/><el-option label="强制取消" value="force-cancel"/><el-option label="重新生成" value="regenerate"/><el-option label="SLA延期" value="sla-waiver"/></el-select></el-form-item><el-form-item v-if="form.action==='sla-waiver'" label="新截止时间" prop="newDueAt"><el-date-picker v-model="form.newDueAt" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss"/></el-form-item><el-form-item label="原因" prop="reason"><el-input v-model="form.reason" type="textarea" :rows="4"/></el-form-item></el-form><span slot="footer"><el-button @click="open=false">取消</el-button><el-button type="danger" :loading="submitting" @click="submit">确认执行</el-button></span></el-dialog></template>
<script>export default{name:'ExceptionActionDialog',props:{visible:Boolean,todo:Object,submitting:Boolean},data(){return{form:{action:'force-complete',reason:'',newDueAt:''},rules:{action:[{required:true}],reason:[{required:true,message:'必须填写操作原因',trigger:'blur'}],newDueAt:[{validator:(r,v,cb)=>this.form.action!=='sla-waiver'||v?cb():cb(new Error('请选择新截止时间')),trigger:'change'}]}}},computed:{open:{get(){return this.visible},set(v){this.$emit('update:visible',v)}}},methods:{submit(){this.$refs.form.validate(ok=>{if(ok)this.$emit('submit',{...this.form})})}}}</script>
